python3 - <<'PY'
from pathlib import Path
from PIL import Image,ImageFilter
import numpy as np, glob, json, hashlib
root=Path('kopf_rgba_tiefe/parallax'); assert root.is_dir()
manifest=root/'manifest.json'; print('MANIFEST_SHA',hashlib.sha256(manifest.read_bytes()).hexdigest())
# Reconstruct the accepted eye mask from source assets, independent of /var/tmp state.
def rgba(p): return np.asarray(Image.open(p).convert('RGBA'))
o=rgba(Path('augen_blink/blink_000.png')); c=rgba(Path('augen_blink/blink_006.png')); g=rgba(Path('augen_gaze/rotglow_tracking_master.png'))[:,:,3]>0
d=np.max(np.abs(o[:,:,:3].astype(np.int16)-c[:,:,:3].astype(np.int16)),axis=2); gy,gx=np.where(g); focus=np.zeros_like(g); focus[max(0,gy.min()-35):min(g.shape[0],gy.max()+36),max(0,gx.min()-35):min(g.shape[1],gx.max()+36)]=1
m=(d>=70)&focus; m=np.asarray(Image.fromarray((m*255).astype('uint8')).filter(ImageFilter.MaxFilter(5)).filter(ImageFilter.MinFilter(5)))>0
# connected components, top2
h,w=m.shape; seen=np.zeros_like(m,bool); comps=[]
for y in range(h):
 for x in range(w):
  if not m[y,x] or seen[y,x]: continue
  q=[(y,x)]; seen[y,x]=1; pts=[]
  while q:
   yy,xx=q.pop(); pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     if not(dx or dy): continue
     ny,nx=yy+dy,xx+dx
     if 0<=ny<h and 0<=nx<w and m[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1; q.append((ny,nx))
  comps.append(pts)
comps=sorted(comps,key=len,reverse=True); base=np.zeros_like(m,bool)
for pts in comps[:2]:
 for y,x in pts: base[y,x]=1
base|=g; hard=np.asarray(Image.fromarray((base*255).astype('uint8')).filter(ImageFilter.MaxFilter(13))); blur=np.asarray(Image.fromarray(hard).filter(ImageFilter.GaussianBlur(4))); mask=np.maximum(hard,blur).astype(np.uint8)
# Map exact live CSS eye mask onto 1536x1024 head canvas.
W,H=1536,1024; x0=round(W*.31); y0=round(H*.12); pw=round(W*.27); ph=round(pw*mask.shape[0]/mask.shape[1]); rm=np.asarray(Image.fromarray(mask).resize((pw,ph),Image.Resampling.LANCZOS)); full=np.zeros((H,W),np.uint8); full[y0:y0+ph,x0:x0+pw]=rm
core=full>=240; mid=full>=128; nz=full>0
# Ring outside eye mask: registration seam risk immediately around canonical overlay.
dil=np.asarray(Image.fromarray((nz*255).astype('uint8')).filter(ImageFilter.MaxFilter(31)))>0; ring=dil&~nz
# broader upper face around eye patch for control.
upper=np.zeros_like(nz); upper[max(0,y0-60):min(H,y0+ph+80),max(0,x0-100):min(W,x0+pw+100)]=1; upper &= ~nz
coeff=np.array([1.0,1/3,-1/3,-1.0],dtype=np.float64)
states=[]
for p in sorted(root.glob('*')):
 if not p.is_dir(): continue
 fs=sorted(p.glob('slice_*.png'));
 if len(fs)!=4: continue
 A=np.stack([np.asarray(Image.open(f).convert('RGBA'))[:,:,3].astype(np.float64)/255 for f in fs])
 asum=A.sum(axis=0); ce=np.divide((A*coeff[:,None,None]).sum(axis=0),asum,out=np.zeros_like(asum),where=asum>1e-9)
 vis=asum>0
 rec={'state':p.name,'files':4,'visible':int(vis.sum())}
 for name,sel in [('EYE_CORE',core&vis),('EYE_MID',mid&vis),('EYE_NZ',nz&vis),('EYE_RING15',ring&vis),('UPPER_CONTROL',upper&vis),('ALL_VISIBLE',vis)]:
  v=ce[sel]; rec[name]={'n':int(v.size),'mean':float(v.mean()) if v.size else None,'abs_mean':float(np.abs(v).mean()) if v.size else None,'p50_abs':float(np.quantile(np.abs(v),.5)) if v.size else None,'p90_abs':float(np.quantile(np.abs(v),.9)) if v.size else None,'p99_abs':float(np.quantile(np.abs(v),.99)) if v.size else None,'max_abs':float(np.abs(v).max()) if v.size else None,'std':float(v.std()) if v.size else None}
 states.append(rec)
print('STATE_COUNT',len(states)); assert len(states)==12,len(states)
for r in states:
 print('STATE',r['state'])
 for name in ['EYE_CORE','EYE_MID','EYE_NZ','EYE_RING15','UPPER_CONTROL','ALL_VISIBLE']:
  s=r[name]; print(name,'N',s['n'],'MEAN',None if s['mean'] is None else round(s['mean'],5),'ABS_MEAN',None if s['abs_mean'] is None else round(s['abs_mean'],5),'P90_ABS',None if s['p90_abs'] is None else round(s['p90_abs'],5),'P99_ABS',None if s['p99_abs'] is None else round(s['p99_abs'],5),'MAX_ABS',None if s['max_abs'] is None else round(s['max_abs'],5),'STD',None if s['std'] is None else round(s['std'],5))
# Aggregate displacement in actual pixels at candidate amplitudes.
for amp in [0.25,0.5]:
 for name in ['EYE_CORE','EYE_NZ','EYE_RING15','UPPER_CONTROL']:
  vals=[]
  for r in states:
   s=r[name];
   if s['p90_abs'] is not None: vals.append(s['p90_abs']*amp)
  print('AMP',amp,name,'P90_EFFECTIVE_PX_ACROSS_STATES_MIN_MED_MAX',round(min(vals),6),round(float(np.median(vals)),6),round(max(vals),6))
# Differential motion between eye core and surrounding ring is the direct seam/registration risk.
for amp in [0.25,0.5]:
 ds=[]
 for r in states:
  ec=r['EYE_CORE']['mean']; er=r['EYE_RING15']['mean'];
  if ec is not None and er is not None: ds.append(abs(ec-er)*amp)
 print('AMP',amp,'CORE_RING_MEAN_DIFFERENTIAL_PX_MIN_MED_MAX',round(min(ds),6),round(float(np.median(ds)),6),round(max(ds),6))
print('MASK_SHA',hashlib.sha256(Image.fromarray(mask).tobytes()).hexdigest(),'MAPPED_CORE_PIXELS',int(core.sum()),'RING_PIXELS',int(ring.sum()))
print('LIVE_MUTATION=0')
print('SCOPE=READ_ONLY_PARALLAX_EYE_REGISTRATION_FIELD')
PY
